using UnityEngine;

public class GameStateController : MonoBehaviour
{
    public enum GameState { MainMenu, Playing, Paused, GameOver }
    public GameState currentState = GameState.MainMenu;
    private GameState previousState;

    void Start()
    {
        previousState = currentState;
        LogState();
    }

    void Update()
    {
        switch (currentState)
        {
            case GameState.MainMenu:
                if (Input.GetKeyDown(KeyCode.Space))
                    currentState = GameState.Playing;
                break;

            case GameState.Playing:
                if (Input.GetKeyDown(KeyCode.Escape))
                    currentState = GameState.Paused;
                break;

            case GameState.Paused:
                if (Input.GetKeyDown(KeyCode.Space))
                    currentState = GameState.Playing;
                break;

            case GameState.GameOver:
                if (Input.GetKeyDown(KeyCode.R))
                    currentState = GameState.MainMenu;
                break;
        }

        if (currentState != previousState)
        {
            LogState();
            previousState = currentState;
        }
    }

    void LogState()
    {
        switch (currentState)
        {
            case GameState.MainMenu: Debug.Log("Main Menu - Press Space to Play"); break;
            case GameState.Playing: Debug.Log("Playing - Press Escape to Pause"); break;
            case GameState.Paused: Debug.Log("Paused - Press Space to Resume"); break;
            case GameState.GameOver: Debug.Log("Game Over - Press R to Restart"); break;
        }
    }
}
